def parsing_error(self, path, exc_info):
    exc_type, exc_value, exc_traceback = exc_info
    exc_lines = "".join(
        traceback.format_exception(exc_type, exc_value, exc_traceback),
    )
    return self._ERROR_MSG.format(
        path=path,
        type=exc_type.__name__,
        body=exc_lines,
    )

